<?php/** * Print value * @param $list * @param bool $exit */function pre($list, $exit = true){    echo "<pre>";    print_r($list);    if ($exit) {        die();    }}/** * Convert slug by lang * @param $arr * @return mixed|string */function convertSlugByLang($arr){    $ci = &get_instance();    $slug = '';    if ($ci->langUrl == LANG_EN) {        $slug = $arr[1];    } else {        $slug = $arr[0];    }    return $slug;}function url_news_cat($slug) {    return base_url($slug);    /*    $ci = &get_instance();    if($ci->langUrl == LANG_EN) {        $link_url = $ci->langUrl.'/news';    } else {        $link_url = 'tin-tuc';    }    if($slug != '') {        $link_url .= "/$slug";    }    */}